# The briefing and checks lists of climb batch 23's two rungs, C and W (CLIMB-BATCH-23.md, section 3), in batch 22's
# form (explorations/compile-ladder/plan-22/manifest/lists22.py) for the batch workflow
# (explorations/coordinator/process-engineering/batch-redesign.md, "The brief"): each list holds what the rung's section
# cites, the decisions, the ledger rows, the notes and the code it rests on, and no process position or harness fact,
# which the brief's role text and the fortress-repo skill carry. POSITIONS and FACTS entries are keyed by their
# numbers. Each briefing entry is a pair: its facts-extract.sh key and one line on why it is there. A checks list is a
# sub-list of its briefing's keys, read by the skeptic, a repair round and a judge. The record's section 5, "The
# briefings, rung by rung", holds the same keys. No key holds a backslash, a backtick or a double quote, which the
# script refuses; facts-extract matches a heading without its backticks.
# `python3 -B lists23.py` checks every key with facts-extract.sh --check (each must match exactly one place) and every
# reason's form; it is run again on the tree the batch is cut from.
SRC = 'ProjectFortress/src/com/sun/fortress/'
NS = "doc:explorations/perf-probes/prelude/natives-shape.md#"
BP = "doc:explorations/perf-probes/prelude/natives-binding-probe.md#"
P23 = "doc:explorations/compile-ladder/plan-23/probes/"
REC = "doc:explorations/coordinator/CLIMB-BATCH-23.md#"

C_BRIEFING = [
  ("P-58", "The decision your rung builds half of: the bare builtinPrimitive form, the rewrite at the parse, the refusal, the check from the first moved binding."),
  ("F-180", "The import java machinery your rewrite goes through, its five gaps on walk, and the two findings that bear on a binding both paths share."),
  ("F-111", "The two stages call the compiled path's phases only, which is why your switch must be on there and the sentence your rung makes false."),
  ("ledger:309", "Your row: builtinPrimitive with no compiled-path counterpart, which the gather closes with your commit."),
  ("ledger:560", "How the checker reads a glue string's body today, which stays so for every string your rewrite leaves alone."),
  (BP + "1. Way 1's compiled half", "The rewrite as the binding probe built and ran it in a shadow: the shapes, the failures, why at the parse, and its cost."),
  (NS + "The names", "The foreign-type table and the well-known types that the switch-over renames, beside which your rung puts a stand-in reading now."),
  (P23 + "rung-C.patch", "Your text as the planner measured it with rung W's: the class, the hooks, the switch, the table and your three tests."),
  (REC + "The planner's probes", "The compiled half's tests, both stages on the two halves and the control that they check a moved binding, on the old base and the new."),
  (REC + "Forks the batch takes, none consequential", "Forks 2 to 5 and 14 to 18, the defaults your rung builds, each with the ways not taken."),
  ("code:" + SRC + "compiler/Parser.java#public static CompilationUnit importCollector(File file)", "The import collector, whose view of a file the repository builds its graph and foreign apis from: your second hook."),
  ("code:" + SRC + "repository/GraphRepository.java#private CompilationUnit readCUFor", "Where the repository reads that view, so a synthetic import must already be in it."),
  ("code:" + SRC + "Shell.java#private static GraphRepository specificRepository(Path p, CacheBasedRepository cache )", "The one place both repositories are made, the compiled path's and walk's: your switch."),
  ("code:" + SRC + "compiler/NamingCzar.java#public static com.sun.fortress.nodes.Type fortressTypeForForeignJavaType(String s, String method_name, boolean isResultType)", "How the checker reads a helper's Java types, the six special names among them, which your stand-in reading points at the one library."),
  ("code:" + SRC + "interpreter/glue/NativeApp.java#public static Applicable checkAndLoadNative(Applicable defn, boolean isFunctionalMethod)", "The body shape walk recognizes as a native, which your rewrite must recognize alike."),
]
C_CHECKS = [
  "P-58", "F-180", "ledger:309", BP + "1. Way 1's compiled half",
  P23 + "rung-C.patch", REC + "The planner's probes",
  "code:" + SRC + "compiler/Parser.java#public static CompilationUnit importCollector(File file)",
  "code:" + SRC + "Shell.java#private static GraphRepository specificRepository(Path p, CacheBasedRepository cache )",
]

W_BRIEFING = [
  ("P-58", "The decision your rung builds half of: walk loads the helper a builtinPrimitive string names, and the bindings move step by step."),
  ("P-29", "Walk's speed is irrelevant to every judgement of performance: the reflective call weighs nothing."),
  ("F-32", "The bindings and their classes, which your rung's first family begins to move, and whose count it changes."),
  ("F-180", "The five gaps of import java on walk and the two findings that bear on a shared binding: the raise and the compiled-world types."),
  ("ledger:796", "Your first row: walk loads a string only as a glue class, which the gather closes with your commit."),
  ("ledger:336", "Your second row: walk's DIV, REM and MOD by zero end the run, of which your family fixes ZZ32's DIV."),
  ("ledger:521", "Why CHOOSE stays on its glue class: its helper fails past its table, which walk would then meet."),
  (NS + "What each gap does to it", "The shape probe's gaps 4 and 5, the conversions and the raise translation your loader takes."),
  (NS + "The library's own construct, walk's half", "The 72-line loader your StaticNativeApp re-bases, measured with the suite green."),
  (P23 + "rung-W.patch", "Your text as the planner measured it with rung C's: the loader, its hook, the family's 21 strings and your five tests."),
  (REC + "The planner's probes", "The loader's tests, the family's texts, the values compared, and the suites on the batch's text, on the old base and the new."),
  (REC + "Forks the batch takes, none consequential", "Forks 6 to 15, the defaults your rung builds, each with the ways not taken."),
  (REC + "Question 2, consequential: the first family in this batch", "The curator's question your family depends on, with what each answer costs."),
  ("code:" + SRC + "interpreter/glue/NativeApp.java#public static Applicable checkAndLoadNative(Applicable defn, boolean isFunctionalMethod)", "Walk's native loader, where your hook goes before the glue class's load."),
  ("code:" + SRC + "interpreter/glue/prim/Int.java#public static FortressError overflow()", "How a native raises the library's IntegerOverflow so that a catch sees it: your raise translation's precedent."),
  ("code:Library/FortressLibrary.fss#trait ZZ32 extends", "Trait ZZ32 in the component, whose 19 bindings your family moves."),
  ("code:ProjectFortress/LibraryBuiltin/FortressBuiltin.fss#value object Int extends ZZ32", "Walk's numeral object Int, whose two getters your family moves and whose asFloat stays."),
  ("code:ProjectFortress/LibraryBuiltin/FortressBuiltin.fsi#The %builtinPrimitive% function is actually recognized..builtinPrimitive[", "The printed comment your rung revises in the revision form."),
  ("doc:Specification/basic/operators/opr-overview.tex#Multiplication, Division, Modulo, and Remainder Operators", "What the specification says of integer division by zero, which your division test cites."),
]
W_CHECKS = [
  "P-58", "ledger:796", "ledger:336", "ledger:521",
  NS + "The library's own construct, walk's half",
  P23 + "rung-W.patch", REC + "The planner's probes",
  "code:" + SRC + "interpreter/glue/NativeApp.java#public static Applicable checkAndLoadNative(Applicable defn, boolean isFunctionalMethod)",
]

IDS = ('C', 'W')
_B = {'C': (C_BRIEFING, C_CHECKS), 'W': (W_BRIEFING, W_CHECKS)}
LISTS = {r: ([k for k, _ in _B[r][0]], _B[r][1]) for r in IDS}
REASONS = {r: _B[r][0] for r in IDS}


def reason_problems(rid):
    out = []
    for k, r in REASONS[rid]:
        if not r or not r.strip():
            out.append((k, 'no reason'))
        elif '\n' in r or '`' in r or any(ord(c) > 127 for c in r):
            out.append((k, 'a reason is one ASCII line with no backtick'))
        elif not r.endswith('.') or len(r) > 240:
            out.append((k, 'a reason ends with a full stop and is at most 240 characters'))
    return out


if __name__ == '__main__':
    import subprocess, re, sys, os
    root = os.environ.get('FORTRESS_HOME', '/home/user/fortress')
    bad = 0
    for rid in IDS:
        b, c = LISTS[rid]
        rp = reason_problems(rid)
        print(rid, 'reasons', len(REASONS[rid]), 'for', len(b), 'briefing keys |', 'problems', len(rp))
        for k, why in rp: print('   PROBLEM', why, ':', k[:200])
        if rp: bad += 1
        for name, keys in (('briefing', b), ('checks', c)):
            if len(set(keys)) != len(keys):
                print('   PROBLEM duplicate key in', rid, name); bad += 1
            badk = [k for k in keys if not k.strip() or k.startswith('-') or re.search(r'["`$\\\n]', k) or any(ord(ch) > 127 for ch in k)]
            if badk:
                print('   PROBLEM keys the script refuses', rid, name, badk); bad += 1
            if name == 'checks':
                stray = [k for k in keys if k not in b]
                if stray:
                    print('   PROBLEM checks keys not in the briefing', rid, stray); bad += 1
            r = subprocess.run(['bash', 'explorations/coordinator/tools/facts-extract.sh', '--check'] + keys, capture_output=True, text=True, cwd=root)
            lines = r.stdout.strip().splitlines()
            probs = [l for l in lines if 'not one' in l or 'NOT FOUND' in l or 'no match' in l.lower() or 'no line of' in l or 'no such file' in l]
            total = [l for l in lines if l.startswith('Total')]
            print(rid, name, 'keys', len(keys), 'exit', r.returncode, '|', total[0] if total else r.stderr.strip()[:200])
            for l in probs: print('   PROBLEM', l[:300])
            if r.returncode or probs:
                bad += 1
                if os.environ.get('VERBOSE'): print(r.stdout)
    print('bad lists', bad)
    sys.exit(1 if bad else 0)
// check23.js for climb batch 23, made from plan-22/manifest/check22.js.
// Checks the MANIFEST block of climb batch 23 (gen23.py's output, $OUT23/manifest23.js) spliced into a scratch copy
// of the workflow script, and with --write splices it into
// the tracked script. As check20.js: node --check on the original and the spliced copy; both parsed as the body of an
// async function, as the Workflow harness parses them, their export made const; every line outside the block
// byte-identical; the block evaluated with the script's own load checks and scatter order; the batch's rungs (C and
// W, in that order, less any that --without names, and never C without W), their fields, no rung bringing a gate step, declaring a
// checker count, a crash or a ladder move; W landing only with C and C with no rung; each section equal to the rung's
// section 3 of the record (backticks dropped, the ellipsis character as three full stops); briefing, reasons and checks
// equal to lists23.py's, one reason per key, checks a sub-list of the briefing; neither rung's test the stage; every
// section naming the count stage and the distance stage; every section saying it makes no speed pass and naming no
// P-148, since no rung changes the checker; no backtick or non-ASCII character in any string the agents read; no text
// asking a skeptic to see a failure again or a stage re-run without a code change (the coordinator skill's
// references/batch.md, "The workflow"); no LEDGER_FROM; the record holding no copy of the block. Its last lines say
// whether the tracked script's block equals the generated one, and count the problems.
//   node check23.js [--without <rung>] [--write] [RECORD]      RECORD defaults to explorations/coordinator/CLIMB-BATCH-23.md
// --without <rung> checks the block that gen23.py writes with the same argument: the batch's rungs less that one.
const fs = require('fs')
const cp = require('child_process')
const path = require('path')
const ROOT = process.env.FORTRESS_HOME || path.resolve(__dirname, '../../../..')
const HERE = process.env.OUT23 || path.join(ROOT, 'tmp')
const SRC = path.join(ROOT, 'explorations/coordinator/climb-batch-workflow.js')
const argv = process.argv.slice(2)
const WRITE = argv.includes('--write')
const WITHOUT = argv.map((a, i) => argv[i - 1] === '--without' ? a : null).filter(a => a !== null)
const BATCH_NAME = '23'
const RUN_IDS = ['C', 'W'].filter(x => !WITHOUT.includes(x))
if (WITHOUT.some(x => !'CW'.includes(x))) { console.log('--without names a rung not in the batch'); process.exit(2) }
if (WITHOUT.includes('C') && !WITHOUT.includes('W')) { console.log('W lands only with C: --without C needs --without W too'); process.exit(2) }
const STAGE_RUNGS = []
const CHECKER_RUNGS = []
const LANDS_ONLY_WITH = { C: [], W: ['C'] }
const REC = argv.filter((a, i) => !a.startsWith('--') && argv[i - 1] !== '--without')[0] || path.join(ROOT, 'explorations/coordinator/CLIMB-BATCH-23.md')
const block = fs.readFileSync(path.join(HERE, 'manifest' + BATCH_NAME + '.js'), 'utf8')
const orig = fs.readFileSync(SRC, 'utf8')
let bad = 0
const say = (ok, text) => { if (!ok) bad++; console.log((ok ? 'ok   ' : 'BAD  ') + text) }

function bounds(text) {
  const ls = text.split('\n')
  const m = ls.findIndex(l => l.startsWith('// MANIFEST - the coordinator replaces'))
  if (m < 1 || !/^\/\/ =+$/.test(ls[m - 1])) throw new Error('no rule above the MANIFEST line')
  const e = ls.findIndex(l => l.startsWith('// =========================== END MANIFEST'))
  if (e < m) throw new Error('no END MANIFEST line after the MANIFEST line')
  return { ls, start: m - 1, end: e }
}
const o = bounds(orig)
const pre = o.ls.slice(0, o.start).join('\n'), post = o.ls.slice(o.end).join('\n')
const current = o.ls.slice(o.start, o.end).join('\n') + '\n'
const spliced = pre + '\n' + block + post
const out = path.join(HERE, 'wf-spliced-' + BATCH_NAME + '.js')
fs.writeFileSync(out, spliced)
console.log('the script\'s MANIFEST block is lines ' + (o.start + 1) + ' to ' + o.end + ' of ' + o.ls.length + '; the generated block has ' + block.split('\n').length + ' lines')
say(spliced.startsWith(pre + '\n') && spliced.endsWith(post) && block.endsWith('\n') && !block.split('\n').some(l => l.startsWith('// =========================== END MANIFEST')), 'every line outside the block is byte-identical, and the block ends before END MANIFEST')

for (const f of [SRC, out]) {
  const r = cp.spawnSync('node', ['--check', f], { encoding: 'utf8' })
  say(r.status === 0, 'node --check ' + path.basename(f) + ': exit ' + r.status + (r.status ? ' ' + r.stderr.trim().slice(0, 300) : ''))
}
const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor
for (const [name, text] of [['original', orig], ['spliced', spliced]]) {
  try { new AsyncFunction('args', 'agent', 'pipeline', 'parallel', 'log', 'phase', 'budget', 'workflow', text.replace(/^export const meta/m, 'const meta')); say(true, 'the harness\'s parse: ' + name + ' accepted as an async function body, its export made const') }
  catch (e) { say(false, 'the harness\'s parse: ' + name + ' refused: ' + e.message) }
}

// The block, evaluated with the script's load checks (const LOOKUP_TOOL ... const keysOf) and its scatter line.
const s = bounds(spliced)
const manifest = s.ls.slice(s.start, s.end).join('\n')
const vStart = s.ls.findIndex(l => l.startsWith('const LOOKUP_TOOL = '))
const vEnd = s.ls.findIndex(l => l.startsWith('const keysOf = '))
const validation = s.ls.slice(vStart, vEnd + 1).join('\n')
const scatter = s.ls.find(l => l.startsWith('const SCATTER = '))
let r = null
try {
  r = new Function("const TOOLS = 'explorations/coordinator/tools'\n" + manifest + '\n' + scatter + '\n' + validation +
    '\nreturn { BATCH, BATCH_RECORD, BRIEFING_LISTS, RUNGS, SCATTER, BATCH_INTRO, ledgerFrom: typeof LEDGER_FROM }')()
  say(true, 'the block passes the script\'s own load checks')
} catch (e) { say(false, 'the block fails the script\'s load checks: ' + e.message) }

if (r) {
  const ids = r.RUNGS.map(x => x.id).join(', ')
  const order = r.RUNGS.slice().sort((a, b) => b.expectedMinutes - a.expectedMinutes).map(x => x.id).join('')
  console.log('batch ' + r.BATCH + ', rungs ' + ids + ', scatter ' + r.SCATTER.map(x => x.id).join('') + ', intro ' + r.BATCH_INTRO.length + ' characters')
  say(r.BATCH === BATCH_NAME && r.BATCH_RECORD === 'explorations/coordinator/CLIMB-BATCH-23.md' && r.BRIEFING_LISTS === 'explorations/compile-ladder/plan-23/manifest/lists23.py' && ids === RUN_IDS.join(', ') && r.SCATTER.map(x => x.id).join('') === order, 'batch ' + BATCH_NAME + ', its record and lists, the rungs ' + RUN_IDS.join(', ') + ' and the scatter by expected minutes, ' + order)
  say(r.ledgerFrom === 'undefined', 'no LEDGER_FROM: the gather numbers the new rows through ledger.py')
  say(r.RUNGS.every(x => Array.isArray(x.gateJoins) && !x.gateJoins.length), 'no rung brings a gate step: testSpecData runs from the last landed summary')
  say(r.RUNGS.every(x => JSON.stringify(x.landsOnlyWith || []) === JSON.stringify(LANDS_ONLY_WITH[x.id])), 'W lands only with C, and C with no rung: ' + r.RUNGS.map(x => x.id + ' [' + (x.landsOnlyWith || []).join(', ') + ']').join(', '))
  say(r.RUNGS.every(x => x.expectedCheckerCrash === undefined && Array.isArray(x.expectedMoves) && !x.expectedMoves.length), 'no rung declares a crash or a ladder move')
  say(r.RUNGS.every(x => x.expectedCheckerCount === undefined), 'no rung declares a checker count: it is reported, never red')

  // The record's section 3, rung by rung, as gen23.py reads it.
  const rec = fs.readFileSync(REC, 'utf8')
  const s3 = rec.slice(rec.indexOf('\n## 3. The rungs\n'), rec.indexOf('\n## 4. '))
  const asAscii = (t) => t.replace(/`/g, '').replace(/…/g, '...')
  function section(id) {
    const m = new RegExp('^### ' + id + '\\. .*$', 'm').exec(s3)
    if (!m) return null
    const rest = s3.slice(m.index + m[0].length)
    const nx = rest.search(/^### /m)
    return asAscii((nx < 0 ? rest : rest.slice(0, nx)).replace(/^\n+|\n+$/g, ''))
  }
  // lists23.py's briefings, reasons and checks.
  const py = cp.spawnSync('python3', ['-B', '-c', 'import json, sys; sys.path.insert(0, sys.argv[1]); from lists23 import LISTS, REASONS, IDS; ' +
    'print(json.dumps({r: {"briefing": LISTS[r][0], "checks": LISTS[r][1], "reasons": [x for _, x in REASONS[r]]} for r in IDS}))', __dirname], { encoding: 'utf8' })
  const lists = py.status === 0 ? JSON.parse(py.stdout) : null
  say(!!lists, 'lists23.py read' + (lists ? '' : ': ' + py.stderr.trim().slice(0, 300)))
  const rerun = /sees? it fail again|re-?run by the skeptic|skeptic re-?runs|run the stage yourself|skeptic rebuilds|re-anchor/i
  for (const x of r.RUNGS) {
    const want = section(x.id)
    say(want !== null && x.section === want, x.id + ': its section is the record\'s section 3 for ' + x.id + ' word for word (' + x.section.length + ' characters)')
    const l = lists && lists[x.id]
    say(!!l && JSON.stringify(x.briefing) === JSON.stringify(l.briefing) && JSON.stringify(x.checks) === JSON.stringify(l.checks) &&
      JSON.stringify(x.reasons) === JSON.stringify(l.reasons.map(asAscii)), x.id + ': briefing ' + x.briefing.length + ' keys, reasons ' + x.reasons.length + ', checks ' + x.checks.length + ', as lists23.py has them')
    say(x.checks.every(k => x.briefing.includes(k)), x.id + ': checks a sub-list of the briefing')
    say(x.branch === 'wip/' + x.slug && /^\/home\/user\/fortress-[a-z0-9-]+$/.test(x.path) && x.expectedMinutes > 0, x.id + ': ' + x.path + ' on ' + x.branch + ', ' + x.expectedMinutes + ' minutes')
    say(Array.isArray(x.pointsToReport) && x.pointsToReport.length > 0 && x.pointsToReport.every(p => typeof p === 'string' && p.trim()), x.id + ': ' + x.pointsToReport.length + ' points to report')
    const texts = [x.title, x.blurb, x.section].concat(x.pointsToReport, x.reasons, x.briefing)
    say(!texts.some(t => /[^\x00-\x7f`]/.test(t) || /`/.test(t)), x.id + ': no backtick or non-ASCII character')
    say(!texts.some(t => rerun.test(t)), x.id + ': nothing asks a skeptic to see a failure again, rebuild, re-run or re-anchor')
    say(x.testIsStage === STAGE_RUNGS.includes(x.id), x.id + ': its test is the stage: ' + x.testIsStage + (STAGE_RUNGS.includes(x.id) ? ', its every edit is library text that only the checker reads differently' : ', a test first'))
    say(/distance stage/.test(x.section) && /count stage/.test(x.section), x.id + ': its section names the count stage and the distance stage')
    if (CHECKER_RUNGS.includes(x.id)) say(/P-148/.test(x.section) && /speed pass/.test(x.section) && !/no speed pass/.test(x.section), x.id + ': a rung that changes the checker, its section names P-148 and its speed pass')
    else say(/no speed pass/.test(x.section) && !/P-148/.test(x.section), x.id + ': a rung outside the checker, its section says it makes no speed pass')
  }
  say(!/[^\x00-\x7f]|`/.test(r.BATCH_INTRO) && !rerun.test(r.BATCH_INTRO), 'the intro: ASCII, no backtick, no re-run')
  const paths = r.RUNGS.map(x => x.path), slugs = r.RUNGS.map(x => x.slug)
  say(new Set(paths).size === paths.length && new Set(slugs).size === slugs.length, 'every rung has its own worktree and branch')
  say(!rec.includes('const RUNGS') && !rec.includes('_ENTRY = {') && rec.includes('gen23.py') && rec.includes('check23.js'), 'the record names gen23.py and check23.js and holds no copy of the block')
}

const same = current === block
console.log((same ? 'the tracked script\'s block equals the generated one' : 'the tracked script\'s block differs from the generated one') + (WRITE ? '' : '; --write splices it'))
if (WRITE) {
  if (bad) console.log('not written: ' + bad + ' problem(s)')
  else if (same) console.log('nothing to write')
  else { fs.writeFileSync(SRC, spliced); console.log('wrote the block into ' + path.relative(ROOT, SRC)) }
}
console.log('problems: ' + bad)

225 glue/StaticNativeApp.java
package com.sun.fortress.interpreter.glue;

import static com.sun.fortress.exceptions.ProgramError.error;
import com.sun.fortress.compiler.runtimeValues.FortressImplementationError;
import com.sun.fortress.exceptions.FortressError;
import com.sun.fortress.interpreter.Driver;
import com.sun.fortress.interpreter.evaluator.values.*;
import com.sun.fortress.nodes.*;
import com.sun.fortress.nodes_util.NodeUtil;
import edu.rice.cs.plt.tuple.Option;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * A native whose builtinPrimitive string names a static Java method of the
 * package com.sun.fortress.nativeHelpers, "com.sun.fortress.nativeHelpers.Class.method",
 * in place of a glue class.  Among the class's public static methods of that
 * name it takes the one whose Java parameter and result types carry the
 * declaration's types; a functional method's self, and a dotted method's self,
 * go first.  It calls the method by reflection, each argument unboxed and the
 * result boxed at the declared result type.  A helper's raise of an exception
 * class of the compiled path, "fortress.<Api>$<Name>", becomes the raise of the
 * library's own exception object <Name>, as Int.overflow() raises IntegerOverflow.
 */
public class StaticNativeApp extends NativeMeth {
    public static final String HELPERS = "com.sun.fortress.nativeHelpers.";

    /** Does s name a helper (a static method of nativeHelpers), not a glue class? */
    public static boolean isHelperString(String s) {
        return s.startsWith(HELPERS);
    }

    private final Method m;
    private final Class<?>[] ps;
    private final String result;     // the declared result type's name
    private final int selfAt;        // index of self among the declared parameters, or -1
    private int arity;

    /** The Java type that carries a value of the named Fortress type, or null. */
    static Class<?> javaFor(String t) {
        if (t == null) return null;
        if (t.equals("ZZ32") || t.equals("NN32") || t.equals("Char")) return int.class;
        if (t.equals("ZZ64") || t.equals("NN64")) return long.class;
        if (t.equals("RR64")) return double.class;
        if (t.equals("RR32")) return float.class;
        if (t.equals("Boolean")) return boolean.class;
        if (t.equals("String") || t.equals("FlatString") || t.equals("JavaString")) return String.class;
        if (t.equals("ZZ")) return BigInteger.class;
        if (t.equals("()")) return void.class;
        return null;
